from stage import Game, Sprite, random_number

game = Game(width=480, height=360, background="#080B18")

ship = Sprite("rocket", x=240, y=310, size=44, name="ship")

rocks = []
for i in range(6):
    rock = Sprite("rock", x=random_number(30, 450), y=random_number(20, 240),
                  size=34, name="rock" + str(i))
    rocks.append(rock)


@game.every_frame
def update():
    # Across.
    if game.key_down("left"):
        ship.x = ship.x - 6
    if game.key_down("right"):
        ship.x = ship.x + 6

    # Up and down. Smaller y is higher up the screen.
    if game.key_down("up"):
        ship.y = ship.y - 6
    if game.key_down("down"):
        ship.y = ship.y + 6

    # Move first, then fix — one line for all four edges.
    game.clamp_inside(ship)

    for rock in rocks:
        rock.y = rock.y + 3
        if rock.y > 380:
            rock.y = -20
            rock.x = random_number(30, 450)


game.start()

from stage import Game, Sprite, Text, random_number

game = Game(width=480, height=360, background="#080B18")

ship = Sprite("rocket", x=240, y=310, size=44, name="ship")

rocks = []
for i in range(6):
    rock = Sprite("rock", x=random_number(30, 450), y=random_number(20, 240),
                  size=34, name="rock" + str(i))
    rocks.append(rock)

game.score = 0
label = Text("Dodged: 0", x=16, y=16, size=20, color="#FFC93C")


@game.every_frame
def update():
    if game.key_down("left"):
        ship.x = ship.x - 6
    if game.key_down("right"):
        ship.x = ship.x + 6
    if game.key_down("up"):
        ship.y = ship.y - 6
    if game.key_down("down"):
        ship.y = ship.y + 6
    game.clamp_inside(ship)

    for rock in rocks:
        rock.y = rock.y + 3

        if rock.y > 380:
            rock.y = -20
            rock.x = random_number(30, 450)
            game.score = game.score + 1
            label.words = "Dodged: " + str(game.score)

        # One line, asked about all six rocks.
        if ship.touching(rock):
            label.words = "CRASH! You dodged " + str(game.score)
            game.stop()


game.start()
